-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الأدب والحياة الاجتماعية في العصر العباسي","passage":"يظهر أثر التحولات الاجتماعية في تطور الأغراض والأساليب الأدبية، لكن كل دعوى عن شاعر أو نص محدد تحتاج مصدرًا تاريخيًا موثقًا. نموذج مستقل: «في مجلس للعلماء يتبادل الحاضرون كتبًا وأسئلة ونقدًا»؛ يساعد على فهم تفاعل الأدب والعلم ولا يصف واقعة تاريخية بعينها.","prompt":"ما الدليل المطلوب لإثبات أثر اجتماعي تاريخي؟","correct":"نص أو مصدر موثق من العصر","w1":"مجرد تخمين","w2":"تكرار الشائعة","w3":"اختلاق قصة شاعر","practice":"كوّن جدولًا يربط ظاهرتين من الحياة العباسية بنصين أدبيين موثقين، مع تفسير العلاقة وحدود الاستنتاج."},{"n":2,"skill":"وصف الطبيعة والصنعة عند البحتري","passage":"قصيدة «وصف بركة المتوكل» للبحتري لا يمكن تحليل ألفاظها تفصيليًا دون النص المقرر. مثال نثري أصلي: «انعكست أضواء الممر على ماء البركة، وبدت الحافة المرصوفة كإطار للصورة». تتعاون ملاحظة المكان والتشبيه في الوصف، لكنه ليس بيتًا للشاعر.","prompt":"ما الشيء المشبه بإطار الصورة في المثال؟","correct":"الحافة المرصوفة","w1":"الماء","w2":"الممر","w3":"الضوء","practice":"استخرج من قصيدة البحتري الموثقة صورة فنية تتعلق بالماء أو المكان واشرح دورها، ثم أنشئ وصفًا مستقلًا."},{"n":3,"skill":"الغرض الشعري وسياقه في شعر المتنبي","passage":"يتطلب «أتوك يجرون الحديد» للمتنبي قراءة الأبيات في سياقها قبل تحديد المخاطب أو الغرض أو استخراج شواهد. تدريب مستقل: «يرى الراوي كتائب تتحرك بنظام، فيصف الأصوات والصور الحركية لتقوية الانطباع». لا يمثل هذا الوصف قصيدة المتنبي.","prompt":"ما العنصر الذي يعطي المشهد إحساسًا بالحركة؟","correct":"وصف تحرك الكتائب","w1":"ذكر اسم شاعر","w2":"حذف الزمن","w3":"إلغاء الأفعال","practice":"بعد قراءة الأبيات الأصلية حلل فعلين وصورة حسية، وبيّن الغرض الشعري مع الاستشهاد."},{"n":4,"skill":"مقومات المقامة في النثر الفني","passage":"تجمع المقامة في أمثلة كثيرة بين السرد والحيلة البلاغية والسجع، لكن «المقامة الموصلية» للهمذاني تحتاج الرجوع إلى نصها الصحيح لذكر الشخصيات والحوادث. نادرة مستقلة: «وعد صاحبُ مجلس ضيوفه بقصة عجيبة، فظل يهيئ المقدمة حتى انتهى الوقت قبل القصة!».","prompt":"أين المفارقة في النادرة المستقلة؟","correct":"انتهاء الوقت قبل سرد القصة","w1":"وجود مجلس","w2":"الاستماع للضيف","w3":"ذكر المدينة","practice":"بعد قراءة المقامة الأصلية حدد الراوي والمفارقة وأثر السجع بأمثلة موثقة، ثم اكتب مشهدًا مستقلًا."},{"n":5,"skill":"المقالة الأدبية المقارنة عن الحضارة العباسية","passage":"لا يكفي سرد أسماء العلماء لوصف الرقي الحضاري في مقالة أدبية؛ يحتاج الكاتب أطروحة وحججًا وشواهد دقيقة من مصادر ذات صلة. نموذج: «أسهم التفاعل بين العلم والأدب في تنوع أساليب التعبير» فرضية عامة تُفحص بنصوص موثقة، لا حقيقة مفصلة عن شخص دون دليل.","prompt":"أي عنصر يجعل المقال مقنعًا تاريخيًا؟","correct":"الشواهد الأدبية الموثقة","w1":"الأوصاف العامة وحدها","w2":"اختلاق اقتباس","w3":"نقل نتائج بلا مصدر","practice":"اكتب مخطط مقالين مختلفين عن مظهرين ثقافيين في العصر العباسي مع شاهد تاريخي موثق لكل مقال."},{"n":6,"skill":"إعداد بحث عن الأدب العباسي","passage":"تنظم الورقة البحثية الجيدة سؤالًا محددًا مثل «كيف يوظف شاعر عباسي وصف المكان؟»، ثم تعرض خلفية موجزة وتحليل نص ومراجع وخاتمة. يميز الباحث الاقتباس الدقيق من إعادة الصياغة، ويذكر الصفحة والطبعة عند الاستشهاد.","prompt":"ما الذي يحدد اتجاه البحث منذ البداية؟","correct":"سؤال بحث واضح","w1":"جمع نصوص عشوائية","w2":"حذف المصادر","w3":"تكرار المقدمة","practice":"أنشئ خطة ورقة بحثية من صفحة واحدة تتضمن سؤالًا ومنهجًا وشاهدين موثقين وقائمة مراجع أولية."},{"n":7,"skill":"علاقة الأدب بالحياة في الأندلس","passage":"تحتاج دراسة الحياة الاجتماعية الأندلسية إلى الجمع بين النصوص الأدبية والمصادر التاريخية مع مراعاة تنوع الحقب والمناطق. في نص تدريبي مستقل وصف كاتبٌ مجلسًا ثقافيًا يجمع الشعر والموسيقى؛ لا يُعد المثال وصفًا تاريخيًا لمجلس بعينه.","prompt":"لماذا يجب تحديد الحقبة والمنطقة عند دراسة الأندلس؟","correct":"لتجنب تعميم تجربة واحدة على جميع العصور","w1":"لإلغاء المصادر","w2":"لنسخ عنوان النص","w3":"لمنع المقارنة","practice":"اكتب فقرة تحليلية عن مظهر أدبي أندلسي بعد الاستناد إلى مصدرين موثوقين وحدد مجال الاستنتاج."},{"n":8,"skill":"وصف العمران في نص موثق","passage":"لتحليل «مدينة الزاهرة» المنسوب في عنوان الدرس إلى ابن هذيل يلزم النص المدرسي الأصلي قبل استخراج أوصاف العمارة أو الحكم على دقة الصورة. مثال من ضاديوم: «تتصل الساحة بممرين تحف بهما الحدائق، ويظهر باب مرتفع في النهاية»؛ وصف مستقل غير منسوب للمؤلف.","prompt":"ما العنصر الذي يجعل الوصف المكاني واضحًا؟","correct":"تحديد علاقات الممرات والساحة","w1":"ذكر اسم شاعر فقط","w2":"إخفاء مواضع الأشياء","w3":"حذف الاتجاهات","practice":"استخرج من نص «مدينة الزاهرة» بعد توثيقه ثلاث صور مكانية، ثم قارنها بوصف من إنشائك."},{"n":9,"skill":"الأدب والنهضة الفكرية الأندلسية","passage":"يمكن دراسة صلة الأدب بالفكر عبر مقارنة نص أدبي بنص علمي أو فلسفي من الفترة نفسها، دون افتراض أن كل مؤلف تبنى الأفكار نفسها. النموذج المستقل: «سأل المتعلم عن سبب اختلاف تفسير الظواهر، فاقترح رفيقه مقارنة الدليل قبل الحكم».","prompt":"ما منهج المتعلم في المثال؟","correct":"مقارنة الأدلة قبل الحكم","w1":"الاكتفاء بقول واحد","w2":"تجاهل المصادر","w3":"رفض الأسئلة","practice":"أعد بطاقة بحث عن كاتب أندلسي مع عمل موثق وفكرة قابلة للاختبار وشاهد صحيح من النص."},{"n":10,"skill":"الحكاية الفلسفية دون اختلاق أحداث","passage":"«حي بن يقظان» لابن طفيل نص معروف في الأدب الفلسفي، لكن تحليل المقطع الدراسي يقتضي الرجوع إلى الكلمات المقررة وتوثيقها. نص مستقل: «راقب طفل تغير ظل شجرة خلال اليوم، وكتب أسئلة عن حركة الضوء»، للتدرب على الاستدلال لا لتمثيل أحداث الحكاية.","prompt":"ما الذي دفع الطفل إلى طرح أسئلته في المثال؟","correct":"ملاحظة تغير ظل الشجرة","w1":"تكرار جواب جاهز","w2":"غياب الشجرة","w3":"عدم مراقبة الضوء","practice":"استخرج من المقطع الأصلي سؤالًا معرفيًا أو وسيلة استدلال موثقة، ثم قارنه بمثال تجربة بسيطة."},{"n":11,"skill":"الموشح والحنين في الشعر الأندلسي","passage":"يحتاج «جادك الغيث» للسان الدين بن الخطيب إلى الأبيات الأصلية لفحص الإيقاع والعاطفة وصيغ النداء. مثال مستقل: «كلما هطل المطر تذكرت الساحة القديمة وأصوات الرفاق». يدل على الحنين لكنه ليس اقتباسًا من الموشح.","prompt":"ما الشعور الغالب في المثال المستقل؟","correct":"الحنين إلى المكان","w1":"اللامبالاة","w2":"التنافس المالي","w3":"الغضب من القراءة","practice":"اقرأ الموشح المقرر وحدد شاهدًا صحيحًا للحنين وبنية إيقاعية ظاهرة دون اختلاق شطر."},{"n":12,"skill":"كتابة مقالين عن الحضارة الأندلسية","passage":"تتطلب مقالة مظاهر الرقي الحضاري تحديد جانب بعينه، مثل وصف العمران أو الحياة الثقافية، ثم تحليل مصدر أدبي موثق بدل قائمة مدائح عامة. في تدريب أصلي يختار طالب مقارنة صورتين للمكان في نصين مع تحديد نقاط التشابه والاختلاف.","prompt":"ما أساس المقارنة العلمية في المقال؟","correct":"شواهد نصية موثقة من النصين","w1":"الانطباع وحده","w2":"اختلاق وصف","w3":"عدم تمييز العصور","practice":"خطط مقالين عن أثر العمران والمعرفة في أدب الأندلس، لكل مقال أطروحة وشاهدان وخاتمة."},{"n":13,"skill":"توثيق الورقة البحثية الأندلسية","passage":"في بحث بعنوان «صورة المدينة في نص أندلسي» يجب ذكر سؤال البحث والنص محل الدراسة وطبعة المصدر وأمثلة مقتبسة قصيرة بدقة مع تفسيرها. يتجنب الطالب نسخ مواقع الإنترنت دون تحقق ويميز الاقتباس من ملاحظاته.","prompt":"أي ممارسة تحافظ على نزاهة الورقة البحثية؟","correct":"ذكر مصادر الاقتباسات وطبعاتها","w1":"حذف المراجع","w2":"نسبة الأمثلة إلى غير أصحابها","w3":"نقل المحتوى دون قراءة","practice":"اكتب مسودة خطة بحث عن نص أندلسي تتضمن سؤالًا ومراجع أولية وخطوات تحليل وملاحظة حدود المعرفة."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='31c82c79-72de-4e4b-a5dc-6f9e598b3533'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 214 — الأدب والحضارة في العصر العباسي والأندلسي (اختياري أساسي)' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G11_T2_ARAB214_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_UNIFIED_G11_T2_ARAB214_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_UNIFIED_G11_T2_ARAB214_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_UNIFIED_G11_T2_ARAB214_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;